CREATE OR REPLACE FUNCTION public.protect_call_invitation() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.caller_id IS DISTINCT FROM OLD.caller_id OR NEW.receiver_id IS DISTINCT FROM OLD.receiver_id OR NEW.audio IS DISTINCT FROM OLD.audio OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Call participants cannot be changed'; END IF; IF OLD.status IN ('ended','declined') AND NEW.status <> OLD.status THEN RAISE EXCEPTION 'Call has already ended'; END IF; IF NEW.status IN ('accepted','declined') AND auth.uid() <> OLD.receiver_id THEN RAISE EXCEPTION 'Only the recipient can answer a call'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.protect_call_invitation() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER protect_call_invitation BEFORE UPDATE ON public.call_invitations FOR EACH ROW EXECUTE FUNCTION public.protect_call_invitation();